contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 amount) public {
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 distributedBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 remainingBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 ownerBalanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(amount <= ownerBalanceBefore);

        c.burn(amount); if (__ESBMC_reverted()) return;

        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 distributedAfter = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 remainingAfter = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 ownerBalanceAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        assert(
            supplyAfter == supplyBefore - amount &&
            distributedAfter == distributedBefore - amount &&
            remainingAfter == remainingBefore &&
            ownerBalanceAfter == ownerBalanceBefore - amount
        );
    }
}

